// 1. Obter texto do CSV da requisição HTTP anterior
const rawCsv = $input.first().json.data || $input.first().json.body || $input.first().text || '';

// 2. Obter clientes recebidos no Webhook
const webhookItem = $('Webhook Clientes').first().json;
let clientes = [];
if (webhookItem.body && Array.isArray(webhookItem.body.clientes)) {
  clientes = webhookItem.body.clientes;
} else if (webhookItem.body && Array.isArray(webhookItem.body)) {
  clientes = webhookItem.body;
} else if (Array.isArray(webhookItem.clientes)) {
  clientes = webhookItem.clientes;
} else if (Array.isArray(webhookItem)) {
  clientes = webhookItem;
} else if (webhookItem.body && typeof webhookItem.body === 'object') {
  clientes = [webhookItem.body];
}

// 3. Parse do CSV
const linhasCsv = rawCsv.trim().split(/\r?\n/);
const cabecalho = linhasCsv[0].split(',').map(c => c.trim().toLowerCase());
const catalogo = [];

for (let i = 1; i < linhasCsv.length; i++) {
  const linha = linhasCsv[i].trim();
  if (!linha) continue;
  const colunas = linha.split(',').map(c => c.trim());
  const item = {};
  cabecalho.forEach((col, idx) => {
    item[col] = colunas[idx] || '';
  });
  item.minimo_valor = parseFloat(item.minimo.replace(/[^0-9.]/g, '')) || 0;
  catalogo.push(item);
}

function converterSaldoParaNumero(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  const limpo = saldoStr.replace(/[^0-9,-]/g, '').replace(/\./g, '').replace(',', '.');
  return parseFloat(limpo) || 0;
}

// 4. Cruzamento dos dados
const clientesProcessados = clientes.map(cliente => {
  const saldoNum = converterSaldoParaNumero(cliente.saldo);
  const perfil = (cliente.perfil || '').trim();

  const produtosPerfil = catalogo.filter(inv =>
    inv.perfil.toLowerCase() === perfil.toLowerCase()
  );

  const produtosAcessiveis = produtosPerfil.filter(inv => saldoNum >= inv.minimo_valor);
  const recomendados = produtosAcessiveis.length > 0 ? produtosAcessiveis : produtosPerfil;

  return {
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    perfil: perfil,
    produtos_recomendados: recomendados.map(p => ({
      produto: p.produto,
      minimo: p.minimo,
      rentabilidade: p.rentabilidade
    }))
  };
});

return clientesProcessados.map(c => ({ json: c }));

