const itens = $input.all();
const resultados = itens.map(item => {
  const dados = item.json;
  return {
    nome: dados.nome,
    email: dados.email,
    perfil: dados.perfil,
    saldo: dados.saldo,
    produtos_recomendados: dados.produtos_recomendados,
    mensagem_gerada_ia: dados.text || dados.response || dados.output,
    modelo_ia: "Google Gemini / LLM",
    processado_em: new Date().toISOString()
  };
});

return {
  json: {
    sucesso: true,
    tipo_processamento: "IA Generativa (LLM)",
    total_clientes: resultados.length,
    timestamp: new Date().toISOString(),
    dados: resultados
  }
};
